  &__step { align-items: center; display: grid; flex: 1 1 0; grid-template-columns: 68px 1fr; grid-template-rows: 68px 38px; position: relative;
    &:not(:last-child)::after { background: #d6d6d6; content: ''; height: 1px; left: 86px; position: absolute; right: 20px; top: 33px; }
